import sys
import sqlite3
import time
import argparse
from collections import defaultdict

def parse_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument('rules_file', type=str)
    parser.add_argument('db_file', type=str)
    parser.add_argument('--max-rows-per-second', type=float, required=True)
    return parser.parse_args()

def parse_rules_file(rules_file):
    with open(rules_file, 'r', encoding='utf-8') as f:
        lines = f.readlines()
    table_name = lines[0].strip()
    columns = [col.strip() for col in lines[1].split(',')]
    rules = []
    for line in lines[2:]:
        if line.strip():
            parts = line.strip().split('\t')
            if len(parts) == 2:
                rule_name, expr = parts
                rules.append((rule_name, expr))
    return table_name, columns, rules

def evaluate_expression(expr, row):
    try:
        # Replace column names with row values
        for col, val in zip(row.columns, row.values):
            expr = expr.replace(col, str(val))
        return eval(expr)
    except:
        return 0

def process_database(db_file, table_name, columns, rules, max_rows_per_second):
    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()
    cursor.execute(f"SELECT * FROM {table_name}")
    rows = cursor.fetchall()
    conn.close()

    rule_counts = defaultdict(int)
    last_row_time = 0
    row_count = 0

    for row in rows:
        row_values = [row[i] for i in range(len(columns))]
        rule_results = []

        for rule_name, expr in rules:
            result = evaluate_expression(expr, row_values)
            rule_results.append(result > 0)

        for i, rule_name in enumerate(rules):
            if rule_results[i]:
                rule_counts[rule_name] += 1

        row_count += 1
        current_time = time.time()
        elapsed = current_time - last_row_time
        if elapsed < 1.0 / max_rows_per_second:
            time.sleep(1.0 / max_rows_per_second - elapsed)
        last_row_time = current_time

    return rule_counts

def main():
    args = parse_arguments()
    table_name, columns, rules = parse_rules_file(args.rules_file)
    rule_counts = process_database(args.db_file, table_name, columns, rules, args.max_rows_per_second)

    for rule_name, count in rule_counts.items():
        print(f"{rule_name}\t{count}")

if __name__ == "__main__":
    main()

import sqlite3
import sys
import time
from collections import defaultdict

def parse_rules(rules_file):
    with open(rules_file, 'r', encoding='utf-8') as f:
        table_name = f.readline().strip()
        columns = f.readline().strip().split(',')
        rules = []
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split('\t')
            if len(parts) != 2:
                continue
            rule_name, expr = parts
            rules.append((rule_name, expr, columns))
    return table_name, columns, rules

def evaluate_expression(row, expr, columns):
    values = {col: row[col] for col in columns}
    try:
        return eval(expr, {'__builtins__': None}, values)
    except:
        return 0

def process_data(db_file, table_name, columns, rules, max_rows_per_second):
    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()
    cursor.execute(f"SELECT {', '.join(columns)} FROM {table_name}")
    rows = cursor.fetchall()
    conn.close()

    rule_counts = defaultdict(int)
    start_time = time.time()
    row_count = 0

    for row in rows:
        row_count += 1
        current_time = time.time()
        elapsed = current_time - start_time
        if elapsed < row_count / max_rows_per_second:
            time.sleep(max_rows_per_second - elapsed)

        for rule_name, expr, _ in rules:
            value = evaluate_expression(row, expr, columns)
            if value > 0:
                rule_counts[rule_name] += 1

        start_time = time.time()

    return rule_counts

def main():
    if len(sys.argv) != 5:
        print("Usage: python apply_rules.py rules.tsv data.sqlite3 --max-rows-per-second N")
        sys.exit(1)

    rules_file = sys.argv[1]
    db_file = sys.argv[2]
    try:
        max_rows_per_second = int(sys.argv[4])
    except ValueError:
        print("N must be an integer greater than 0")
        sys.exit(1)

    table_name, columns, rules = parse_rules(rules_file)
    rule_counts = process_data(db_file, table_name, columns, rules, max_rows_per_second)

    for rule_name in sorted(rules, key=lambda x: x[0]):
        print(f"{rule_name[0]}\t{rule_counts[rule_name]}")

if __name__ == "__main__":
    main()

